(465, 249, '_form', '<div class=\"custom-row\">\n    <div class=\"custom-col-6\"><label>[text* first-name placeholder \"Enter Your Name\"]</label></div>\n<div class=\"custom-col-6\"><label>[email* your-email placeholder \"Enter Your Email\"] </label></div>  \n</div>\n<div class=\"custom-row\">\n    <div class=\"custom-col-12\">\n        <label><span style=\"display:none\">Buyer Type</span> [select* select-1 first_as_label \"Select Buyer Type\" \"New Buyer\" \"Returning Customer\"]</label>\n    </div>\n</div>\n<div class=\"custom-row\">\n    <div class=\"custom-col-12\">    \n        [submit \"Sign Up for Seasonal Updates\"]\n    </div>\n</div>'),
(466, 249, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:57:\"New Seasonal Update Sign-Up — [first-name] just joined!\";s:6:\"sender\";s:36:\"[_site_title] <info@bariproduce.com>\";s:9:\"recipient\";s:24:\"jbedwell@bariproduce.com\";s:4:\"body\";s:4683:\"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n</head>\n<body style=\"margin:0;padding:0;background-color:#f9f3f4;font-family:Georgia,serif;\">\n\n  <!-- Header with Logo -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#61222829;\">\n    <tr>\n      <td align=\"center\" style=\"padding:30px 20px;\">\n        <img src=\"https://bariproduce.com/wp-content/uploads/2026/02/bari-color.png\" \n             alt=\"Bari Produce\" \n             style=\"max-width:180px;height:auto;display:block;\" />\n      </td>\n    </tr>\n  </table>\n\n  <!-- Main Card -->\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n    <tr>\n      <td align=\"center\" style=\"padding:40px 20px;\">\n        <table width=\"600\" cellpadding=\"0\" cellspacing=\"0\" \n               style=\"background:#ffffff;border-radius:8px;overflow:hidden;\n                      box-shadow:0 2px 12px rgba(97,34,40,0.10);max-width:600px;width:100%;\">\n\n          <!-- Greeting -->\n          <tr>\n            <td style=\"padding:40px 40px 20px 40px;\">\n              <h1 style=\"margin:0 0 10px 0;font-size:26px;color:#612228;font-family:Georgia,serif;\">\n                🎉 New Sign-Up Received!\n              </h1>\n              <p style=\"margin:0;font-size:16px;color:#555555;line-height:1.6;\">\n                Great news — someone just signed up for your seasonal updates. \n                Here are their details:\n              </p>\n            </td>\n          </tr>\n\n          <!-- Divider -->\n          <tr>\n            <td style=\"padding:0 40px;\">\n              <hr style=\"border:none;border-top:2px solid #f9f3f4;margin:0;\">\n            </td>\n          </tr>\n\n          <!-- Contact Details -->\n          <tr>\n            <td style=\"padding:30px 40px;\">\n              <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n\n                <tr>\n                  <td style=\"padding:10px 0;border-bottom:1px solid #f9f3f4;\">\n                    <span style=\"font-size:12px;text-transform:uppercase;\n                                 letter-spacing:1px;color:#999999;display:block;\n                                 margin-bottom:4px;\">Name</span>\n                    <span style=\"font-size:17px;color:#222222;font-weight:bold;\">\n                      [first-name]\n                    </span>\n                  </td>\n                </tr>\n\n                <tr>\n                  <td style=\"padding:10px 0;border-bottom:1px solid #f9f3f4;\">\n                    <span style=\"font-size:12px;text-transform:uppercase;\n                                 letter-spacing:1px;color:#999999;display:block;\n                                 margin-bottom:4px;\">Email Address</span>\n                    <span style=\"font-size:17px;color:#612228;font-weight:bold;\">\n                      <a href=\"mailto:[your-email]\" \n                         style=\"color:#612228;text-decoration:none;\">[your-email]</a>\n                    </span>\n                  </td>\n                </tr>\n\n                <tr>\n                  <td style=\"padding:10px 0;\">\n                    <span style=\"font-size:12px;text-transform:uppercase;\n                                 letter-spacing:1px;color:#999999;display:block;\n                                 margin-bottom:4px;\">Customer Type</span>\n                    <span style=\"font-size:17px;color:#222222;font-weight:bold;\">\n                      [select-1]\n                    </span>\n                  </td>\n                </tr>\n\n              </table>\n            </td>\n          </tr>\n\n          <!-- CTA Button -->\n          <tr>\n            <td style=\"padding:10px 40px 40px 40px;\">\n              <a href=\"https://app.constantcontact.com/pages/contacts/ui#contact-list\" \n                 style=\"display:inline-block;background-color:#612228;color:#ffffff;\n                        text-decoration:none;padding:14px 28px;border-radius:4px;\n                        font-size:15px;font-family:Georgia,serif;\">\n                View in Constant Contact →\n              </a>\n            </td>\n          </tr>\n\n          <!-- Footer -->\n          <tr>\n            <td style=\"background-color:#f9f3f4;padding:24px 40px;border-radius:0 0 8px 8px;\">\n              <p style=\"margin:0;font-size:13px;color:#999999;line-height:1.6;\">\n                This contact has been automatically added to your Constant Contact list.<br>\n                Submitted via the sign-up form on \n                <a href=\"https://bariproduce.com\" \n                   style=\"color:#612228;text-decoration:none;\">bariproduce.com</a>\n              </p>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n\n</body>\n</html>\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
