ation_intensity_slide=\"10%\" title_text_color=\"#0A0A0A\" custom_margin=\"||10px||false|false\"][/et_pb_heading][et_pb_heading title=\"We are smaller by design, and hands-on by choice.\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" title_font_size_last_edited=\"on|desktop\" title_font_size=\"22px\" hover_enabled=\"0\" sticky_enabled=\"0\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_text_align=\"left\" title_text_color=\"#612228\" title_level=\"h5\" title_font=\"Inter|600|||||||\" custom_margin=\"||10px||false|false\" title_line_height=\"1.4em\" locked=\"off\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" text_text_color=\"gcid-body-color\" hover_enabled=\"0\" sticky_enabled=\"0\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\"]We’re intentionally structured to stay involved. Orders aren’t passed along anonymously. They’re managed by people who understand fruit, timing, and what’s at stake when product hits the dock.\n\nWe stay close to the field, close to our trusted growers, and accountable through every delivery. That’s how we continue to deliver fruit that is consistent in size, flavor, and appearance - even during busy seasons.\n\nOrdering is straightforward. Communication is clear. And expectations are met without needing reminders.[/et_pb_text][et_pb_heading title=\"We’re big enough to deliver—and small enough to care.\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" title_font_size_last_edited=\"on|desktop\" title_font_size=\"22px\" hover_enabled=\"0\" sticky_enabled=\"0\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_text_align=\"left\" title_text_color=\"#612228\" title_level=\"h5\" title_font=\"Inter|600|||||||\" custom_margin=\"||10px||false|false\" title_line_height=\"1.4em\" locked=\"off\"][/et_pb_heading][et_pb_button button_text=\"Get a Custom Quote\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" custom_button=\"on\" button_text_size=\"16px\" button_bg_color=\"#612228\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color=\"#FFFFFF\" button_text_color__hover_enabled=\"on|hover\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" custom_padding=\"10px|40px|10px|20px|true|false\" button_border_radius=\"16px\" button_bg_enable_color=\"on\" hover_enabled=\"0\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate_linked__hover=\"off\" transform_translate__hover=\"8px|0px\" button_on_hover=\"off\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" theme_builder_area=\"post_content\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" custom_padding_last_edited=\"on|phone\"][/et_pb_section]', 'Home', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2026-02-12 08:25:49', '2026-02-12 08:25:49', '', 12, 'https://bariproduce.com/?p=106', 0, 'revision', '', 0);
