e|false\" title_line_height=\"1.4em\" locked=\"off\"][/et_pb_heading][et_pb_button button_text=\"Get a Custom Quote\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" custom_button=\"on\" button_text_size=\"16px\" button_bg_color=\"#612228\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color=\"#FFFFFF\" button_text_color__hover_enabled=\"on|hover\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" custom_padding=\"10px|40px|10px|20px|true|false\" button_border_radius=\"16px\" button_bg_enable_color=\"on\" hover_enabled=\"0\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate_linked__hover=\"off\" transform_translate__hover=\"8px|0px\" button_on_hover=\"off\" animation_direction=\"top\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" theme_builder_area=\"post_content\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" custom_padding_last_edited=\"on|phone\"][/et_pb_section]', 'Home', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2026-02-12 08:28:05', '2026-02-12 08:28:05', '', 12, 'https://bariproduce.com/?p=110', 0, 'revision', '', 0);
