itle_font_size=\"22px\" hover_enabled=\"0\" sticky_enabled=\"0\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_level=\"h5\" title_font=\"Inter|600|||||||\" custom_margin=\"||10px||false|false\" width=\"60%\" title_line_height=\"1.4em\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" text_text_color=\"#FFFFFF\" hover_enabled=\"0\" sticky_enabled=\"0\" custom_margin=\"||30px||false|false\" width=\"70%\"]<p>We believe great fruit starts with care, experience, and accountability. That’s how we’ve done it for generations—and how we continue to serve today’s marketplace.</p>[/et_pb_text][et_pb_button button_text=\"Get Our Seasonal Updates\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" button_alignment=\"left\" custom_button=\"on\" button_text_size=\"16px\" button_bg_color=\"#9B693F\" button_bg_enable_color=\"on\" button_text_color=\"#FFFFFF\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_text_color__hover_enabled=\"on|hover\" hover_enabled=\"0\" sticky_enabled=\"0\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" custom_padding=\"10px|40px|10px|20px|true|false\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate_linked__hover=\"off\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" theme_builder_a