ds that mattered to our patriarch in Italy still guide us today. They show up in how we select fruit, how we work with growers, and how we serve our customers.</p>[/et_pb_text][et_pb_button button_text=\"The Story Behind Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" custom_button=\"on\" button_text_size=\"16px\" button_bg_color=\"#612228\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color=\"#FFFFFF\" button_text_color__hover_enabled=\"on|hover\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" custom_padding=\"10px|40px|10px|20px|true|false\" button_border_radius=\"16px\" button_bg_enable_color=\"on\" hover_enabled=\"0\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate_linked__hover=\"off\" transform_translate__hover=\"8px|0px\" button_on_hover=\"off\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_2\" theme_builder_area=\"post_content\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/aboutfamily-scaled.webp\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" title_text=\"aboutfamily\" hover_enabled=\"0\" sticky_enabled=\"0\" border_radii=\"on|16px|16px|16px|16px\" border_width_bottom=\"6px\" border_color_bottom=\"#906469\" border_width_bottom__hover_enabled=\"on|hover\" filter_contrast__hover_enabled=\"on|desktop\" filter_satu