(140, 2, '2026-02-12 10:23:24', '2026-02-12 10:23:24', '[et_pb_section fb_built=\"1\" theme_builder_area=\"post_content\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" hover_enabled=\"0\" sticky_enabled=\"0\" custom_padding_last_edited=\"on|phone\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" title_text=\"Flavorosa Plum_B\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/02/Flavorosa-Plum_B-1-scaled.webp\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"#612228 0%|rgba(112,34,42,0.5) 100%\" background_color_gradient_overlays_image=\"on\" background_size=\"contain\" background_position=\"bottom_right\" background_horizontal_offset=\"-15%\" background_enable_color=\"off\" background_color_gradient_direction=\"90deg\"][et_pb_row _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" width=\"90%\" hover_enabled=\"0\" sticky_enabled=\"0\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\"][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"4_4\" theme_builder_area=\"post_content\"][et_pb_heading title=\"Bari Produce Delivers Fruit Customers Come Back For, Week After Week\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" title_font_size_last_edited=\"on|desktop\" title_font_size=\"56px\" hover_enabled=\"0\" sticky_enabled=\"0\" title_font_size_tablet=\"42px\" title_font_size_phone=\"36px\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" custom_margin=\"||10px||false|false\" width=\"75%\"][/et_pb_heading][et_pb_heading title=\"Central California Grown Fruit, From A Family That’s Been Doing This For Generations\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" title_font_size_last_edited=\"on|desktop\" title_font_size=\"22px\" hover_enabled=\"0\" sticky_enabled=\"0\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_level=\"h5\" title_font=\"Inter|600|||||||\" custom_margin=\"||10px||false|false\" width=\"60%\" title_line_height=\"1.4em\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" text_text_color=\"#FFFFFF\" hover_enabled=\"0\" sticky_enabled=\"0\" custom_margin=\"||30px||false|false\" width=\"70%\"]<p>We believe great fruit starts with care, experience, and accountability. That’s how we’ve done it for generations—and how we continue to serve today’s marketplace.</p>[/et_pb_text][et_pb_button button_text=\"Get Our Seasonal Updates\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" button_alignment=\"left\" custom_button=\"on\" button_text_size=\"16px\" button_bg_color=\"#9B693F\" button_bg_enable_color=\"on\" button_text_color=\"#FFFFFF\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_text_color__hover_enabled=\"on|hover\" hover_enabled=\"0\" sticky_enabled=\"0\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" custom_padding=\"10px|40px|10px|20px|true|false\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate_linked__hover=\"off\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" theme_builder_a