gcid-body-color%22:%91%22text_text_color%22%93}\" text_text_color=\"gcid-body-color\" hover_enabled=\"0\" sticky_enabled=\"0\" animation_direction=\"top\"]<p><strong>Table Grapes</strong> under the BARI® and LOGOLUSO® labels and standards<br /><strong>Stone Fruit</strong> such as peaches, nectarines, plums, pluots, cherries, and pomegranates.<br /><strong>Specialty &amp; Seasonal Varieties</strong> like our popular Crazy Apes™ extra large apricots that are all hand-picked and hand-packed.</p>[/et_pb_text][/et_pb_column][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"3_5\" theme_builder_area=\"post_content\"][et_pb_gallery _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" gallery_ids=\"156,153\" show_title_and_caption=\"off\" show_pagination=\"off\" background__hover_enabled=\"on|desktop\" hover_enabled=\"0\" sticky_enabled=\"0\" orientation=\"portrait\" hover_icon=\"&#x2d;||divi||400\" hover_overlay_color=\"rgba(113,56,62,0.74)\" zoom_icon_color=\"#FFFFFF\" border_radii_image=\"on|12px|12px|12px|12px\" custom_margin=\"||0px||false|false\" custom_padding=\"||||false|false\" module_class=\"products-gallery\" posts_number=\"2\"][/et_pb_gallery][/et_pb_column][/et_pb_row][et_pb_row _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" column_structure=\"1_3,2_3\" width=\"90%\" hover_enabled=\"0\" sticky_enabled=\"0\" custom_padding=\"0px||0px||true|false\" locked=\"off\" custom_margin=\"50px||||false|false\" make_equal=\"on\" use_custom_gutter=\"on\"][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_3\" theme_builder_area=\"post_content\" hover_enabled=\"0\" sticky_enabled=\"0\"][et_pb_gallery _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" gallery_ids=\"67\" show_title_and_caption=\"off\" show_pagination=\"off\" sticky_enabled=\"0\" orientation=\"portrait\" hover_icon=\"&#x2d;||divi||400\" hover