px||true|false\" column_structure=\"1_4,1_4,1_4,1_4\" hover_enabled=\"0\" sticky_enabled=\"0\"][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_4\" theme_builder_area=\"post_content\"][et_pb_blurb title=\"01\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" header_level=\"h2\" header_font_size=\"80px\" header_text_align=\"left\" header_font=\"--et_global_heading_font|500|||on||||\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" header_text_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" sticky_enabled=\"0\" height=\"100%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" background_color=\"#612228\"]<p>Stronger displays that hold their shape.</p>[/et_pb_blurb][/et_pb_column][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_4\" theme_builder_area=\"post_content\"][et_pb_blurb title=\"02\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" header_level=\"h2\" header_font_size=\"80px\" header_text_align=\"left\" header_font=\"--et_global_heading_font|500|||on||||\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" header_text_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" height=\"100%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" background_color=\"#612228\"]<p>Fewer calls about condition or hold.</p>[/et_pb_blurb][/et_pb_column][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_4\" theme_builder_area=\"post_content\"][et_pb_blurb title=\"03\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" header_level=\"h2\" header_font_size=\"80px\" header_text_align=\"left\" header_font=\"--et_global_heading_font|500|||on||||\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" header_text_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" height=\"100%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" background_color=\"#612228\"]<p>Better sell-through and cleaner rotation.</p>[/et_pb_blurb][/et_pb_column][et_pb_column _builder_version=\"4.27.5\" _module_preset=\"default\" type=\"1_4\" theme_builder_area=\"post_content\"][et_pb_blurb title=\"04\" _builder_version=\"4.27.5\" _module_preset=\"default\" theme_builder_area=\"post_content\" sticky_enabled=\"0\" header_level=\"h2\" header_font_size=\"80px\" header_text_align=\"left\" header_font=\"--et_global_heading_font|500|||on||||\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" header_text_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" height=\"100%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" background_color=\"#612228\" hover_enabled=\"0\"]<p>Less mental load managing one more variable.</p>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section]', 'Home', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2026-02-13 11:24:05', '2026-02-13 11:24:05', '', 12, 'https://bariproduce.com/?p=226', 0, 'revision', '', 0);
