8\"]<p>Fewer calls about condition or hold.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"03\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\" background_color=\"#612228\"]<p>Better sell-through and cleaner rotation.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"04\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\" background_color=\"#612228\"]<p>Less mental load managing one more variable.</p>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section]', 'Home', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2026-02-13 11:51:1