n_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Bari Fruit Makes Your Shelves Look Good\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_text_color=\"#0A0A0A\" title_font_size=\"36px\" custom_margin=\"||10px||false|false\" animation_direction=\"top\" title_font_size_tablet=\"32px\" title_font_size_phone=\"28px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font|500|||||||\" text_text_color=\"#612228\" text_font_size=\"20px\" global_colors_info=\"{}\"]<p>The highest compliment is when we hear <em>“I saw your fruit in the store. It looked so good, I had to buy it!”</em></p>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font||||||||\" text_text_color=\"#1A1A1A\" global_colors_info=\"{}\"]Our labels mean we are proud of our product. Not everything makes the cut, and that’s intentional. \nWe prioritize long-term relationships over short-term volume, and we protect the standards that buyers trust.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/BariProduceGrapeBo.png\" alt=\"BariProduceGrapeBox\" title_text=\"BariProduceGrapeBox\" _builder_version=\"4.27.5\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" make_equal=\"on\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_marg