yers trust.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/BariProduceGrapeBo.png\" alt=\"BariProduceGrapeBox\" title_text=\"BariProduceGrapeBox\" _builder_version=\"4.27.5\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_phone=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_last_edited=\"on|phone\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" make_equal=\"on\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"50px||||false|false\" custom_margin_tablet=\"50px||||false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"01\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{}\" header_text_color__hover_enabled=\"on|hover\" header_text_color__hover=\"#FFFFFF\"]<p>Stronger displays that hold their shape.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_