e|false\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"1_2\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/about-Us-head.png\" _builder_version=\"4.27.5\" _module_preset=\"default\" alt=\"about\" title_text=\"about-Us-head\" hover_enabled=\"0\" sticky_enabled=\"0\" width=\"30%\" custom_margin=\"||30px||false|false\"][/et_pb_image][et_pb_heading title=\"Our Family Approach To Consistent Quality and Reliable Service\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"36px\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" title_font_size_tablet=\"32px\" title_font_size_phone=\"28px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<p>Our roots trace back to family farming and the open markets of Bari, Italy, where freshness, care, and pride shaped how produce was grown, sold, and valued. Those values carried our family to Central California and continue today through how we manage sales, standards, and stewardship.<br />The standards that mattered to our patriarch in Italy still guide us today. They show up in how we select fruit, how we work with growers, and how we serve our customers.</p>[/et_pb_text][et_pb_button button_text=\"The Story Behind Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_c