 animation_direction=\"top\" global_colors_info=\"{}\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color__hover_enabled=\"on|hover\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate__hover=\"8px|0px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"2_5,3_5\" use_custom_gutter=\"on\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"0px||||false|false\" custom_padding=\"0px||0px||true|false\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"2_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Our Bari Fruit\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_text_align=\"left\" title_text_color=\"#0A0A0A\" title_font_size=\"36px\" custom_margin=\"||0px||false|false\" custom_padding=\"||0px||false|false\" animation_direction=\"top\" title_font_size_tablet=\"32px\" title_font_size_phone=\"28px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_heading title=\"We are smaller by design, and hands-on by choice.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600||