xt_text_color=\"#612228\" text_font_size=\"20px\" global_colors_info=\"{}\"]<p>The highest compliment is when we hear <em>“I saw your fruit in the store. It looked so good, I had to buy it!”</em></p>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font||||||||\" text_text_color=\"#1A1A1A\" global_colors_info=\"{}\"]Our labels mean we are proud of our product. Not everything makes the cut, and that’s intentional. \nWe prioritize long-term relationships over short-term volume, and we protect the standards that buyers trust.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/BariProduceGrapeBo.png\" alt=\"BariProduceGrapeBox\" title_text=\"BariProduceGrapeBox\" _builder_version=\"4.27.5\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_phone=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_last_edited=\"on|phone\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" make_equal=\"on\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"50px||||false|false\" custom_margin_tablet=\"50px||||false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"01\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" bod