  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Better sell-through and cleaner rotation.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"04\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" body_font_size=\"18px\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Less mental load managing one more variable.</p>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" overflow-x=\"visible\" overflow-y=\"visible\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"1_2,1_2\" use_custom_gutter=\"on\" make_equal=\"on\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"||||false|false\" custom_margin_tablet=\"50px||||false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"1_2\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Get Seasonal Updates Straight from Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_text_color=\"#0A0A0A\" title_font_size=\"36px\" custom_margin=\"||10px||false|false\" animation_direction=\"top\" title_font_size_tablet=\"32px\" title_font_size_phone=\"28px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_heading title=\"Sign up for crop updates, availability, and what’s coming next\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|500|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" custom_margin=\"||0px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][/et_pb_column][et_pb_column type=\"1_2\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_code _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][contact-form-7 id=\"2af7f9d\" title=\"Get In Touch\"][/et_pb_code][/et_pb_column][/et_pb_row][/et_pb_section]', 'Home', '', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2026-02-26 09:48:59', '2026-02-26 09:48:59', '', 12, 'https://bariproduce.com/?p=260', 0, 'revision', '', 0);
