on stone fruit and grapes, our programs are built around timing, experience, and restraint.</p>[/et_pb_text][et_pb_button button_text=\"View Seasonal Availability \" button_alignment=\"left\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#9B693F\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" locked=\"off\" global_colors_info=\"{}\" button_text_color__hover_enabled=\"on|hover\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column type=\"2_5\" _builder_version=\"4.16\" custom_padding=\"|||\" global_colors_info=\"{}\" custom_padding__hover=\"|||\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/pomegranate-scaled.webp\" title_text=\"pomegranate\" force_fullwidth=\"on\" align_tablet=\"center\" align_phone=\"\" align_last_edited=\"on|phone\" _builder_version=\"4.27.5\" transform_scale_tablet=\"\" transform_scale_phone=\"\" transform_scale_last_edited=\"on|phone\" transform_translate_tablet=\"\" transform_translate_phone=\"\" transform_translate_last_edited=\"on|phone\" transform_rotate_tablet=\"\" transform_rotate_phone=\"\" tr