_color%22%93}\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\"][/et_pb_heading][et_pb_heading title=\"We are smaller by design, and hands-on by choice.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_direction=\"top\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\"]We’re intentionally structured to stay involved. Orders aren’t passed along anonymously. They’re managed by people who understand fruit, timing, and what’s at stake when product hits the dock.\n\nWe stay close to the field, close to our trusted growers, and accountable through every delivery. That’s how we continue to deliver fruit that is consistent in size, flavor, and appearance - even during busy seasons.\n\nOrdering is straightforward. Communication is clear. And expectations are met without needing reminders.[/et_pb_text][et_pb_heading title=\"We’re big enough to deliver—and small enough to care.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_button button_text=\"Get a Custom Quote\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_col