onal Varieties</strong> like our popular Crazy Apes™ extra large apricots that are all hand-picked and hand-packed.</p>[/et_pb_text][et_pb_button button_text=\"View All Our Products\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#612228\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_direction=\"top\" locked=\"off\" global_colors_info=\"{}\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color__hover_enabled=\"on|hover\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate__hover=\"8px|0px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column type=\"3_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_gallery gallery_ids=\"156,153\" posts_number=\"2\" orientation=\"portrait\" show_title_and_caption=\"off\" show_pagination=\"off\" zoom_icon_color=\"#FFFFFF\" hover_overlay_color=\"rgba(113,56,62,0.74)\" hover_icon=\"&#x2d;||divi||400\" module_class=\"products-gallery\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_margin=\"||0px||false|false\" custom_padding=\"||||false|false\" border_radii_image=\"on|12px|12px|12px|12px\" global_colors_info=\"{}\" background__hover_enabled=\"on|desktop\"][/et_pb_gallery][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"2_5,3_5\" use_custom_gutter=\"on\" make_equal=\"on\" modu