x\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22header_2_text_color%22%93}\" sticky_enabled=\"0\" width=\"80%\" module_alignment=\"left\"]<h2>Industry <span class=\"clr-txt\">Affiliations</span></h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" sticky_enabled=\"0\"]Bari Produce is proud to be actively engaged in the produce industry. Our affiliations reflect our commitment to professionalism, accountability, and staying informed as the marketplace evolves.\n\nWe value collaboration, shared standards, and ongoing learning because delivering consistent quality requires staying connected to the industry as a whole.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/BariProduceGrapeBo.png\" alt=\"BariProduceGrapeBox\" title_text=\"BariProduceGrapeBox\" _builder_version=\"4.27.5\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" hover_enabled=\"0\" scroll_vertical_motion_tablet=\"0|50|50|100|0|0|0\" scroll_vertical_motion_phone=\"0|50|50|100|0|0|0\" scroll_vertical_motion_last_edited=\"on|desktop\" global_colors_info=\"{}\" locked=\"off\" sticky_enabled=\"0\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" hover_enabled=\"0\" locked=\"off\" global_color