der_font_size_phone=\"34px\" header_font_size_last_edited=\"on|desktop\" header_2_font_size_tablet=\"36px\" header_2_font_size_phone=\"34px\" header_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22header_2_text_color%22%93}\" sticky_enabled=\"0\" width=\"80%\" module_alignment=\"left\"]<h2>Our Growers Are <span class=\"clr-txt\">Third-Generation Farming Families</span>, Working Together</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" sticky_enabled=\"0\"]We partner with growers who share our values and our commitment to quality. Many are third-generation farming families with deep roots in Central California agriculture. These are relationships built over time, grounded in trust, and strengthened by shared standards.[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" sticky_enabled=\"0\"]Our growers take pride in their land, their fruit, and their craft. We work closely with them throughout the season, staying involved from the field forward to ensure fruit meets the expectations tied to the Bari® and Logoluso® names.[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" hover_enabled=\"0\" locked=\"off\" global_colors_info=\"{}\" sticky_enabled=\"0\" background_enable_color=\"off\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"#612228 0%|#71383e 99%\" background_color_gradient_direction=\"90deg\"][et_pb_row column_structure=\"2_5,3_5\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" hover_enabled=\"0\" locked=\"off\" global_colors_info=\"{}\" custom_margin=\"||||false|false\" sticky_enabled=\"0\" use_custom_gutter=\"on\"][et_pb_column type=\"2_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" header_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_text_align=\"center\" header_text_color=\"#612228\" header_font_size=\"40px\" header_2_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_2_text_color=\"#FFFFFF\" header_2_font_size=\"40px\" header_3_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_3_text_align=\"center\" header_3_text_color=\"#612228\" header_3_font_size=\"40px\" header_4_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_4_text_align=\"center\" header_4_text_color=\"#612228\" header_4_font_size=\"40px\" header_5_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_5_text_align=\"center\" header_5_text_color=\"#612228\" header_5_font_size=\"40px\" header_6_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_6_text_align=\"center\" header_6_text_color=\"#612228\" header_6_font_size=\"40px\" hover_enabled=\"0\" header_font_size_tablet=\"36px\" header_font_size_phone=\"34px\" header_font_size_last_edited=\"on|desktop\" header_2_font_size_tablet=\"36px\" header_2_font_size_phone=\"34px\" header_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\" sticky_enabled=\"0\" width=\"80%\" module_alignment=\"left\"]<h2>Industry Affiliations</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"#FFFFFF\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{}\" sticky_enabled=\"0\"]<p>Bari Produce is proud to be actively engaged in the produce industry. Our affiliations reflect our commitment to professionalism, accountability, and staying informed as the marketplace evolves.</p>\n<p>We value collaboration, shared standards, and ongoing learning because delivering consistent quality requires staying connected to the industry as a whole.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"3_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_text=\"logos-7-1\" hover_enabled=\"0\" sticky_enabled=\"0\" module_class=\" image-logo\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_text=\"logos-7-1\" hover_enabled=\"0\" sticky_enabled=\"0\" module_class=\" image-logo\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_text=\"logos-7-1\" hover_enabled=\"0\" sticky_enabled=\"0\" module_class=\" image-logo\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_text=\"logos-7-1\" hover_enabled=\"0\" sticky_enabled=\"0\" module_class=\" image-logo\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section]', 'About', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-03-02 06:26:06', '2026-03-02 06:26:06', '', 15, 'https://bariproduce.com/?p=321', 0, 'revision', '', 0);
