=\"center\" header_5_text_color=\"#612228\" header_5_font_size=\"40px\" header_6_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_6_text_align=\"center\" header_6_text_color=\"#612228\" header_6_font_size=\"40px\" width=\"60%\" module_alignment=\"center\" hover_enabled=\"0\" header_font_size_tablet=\"36px\" header_font_size_phone=\"34px\" header_font_size_last_edited=\"on|desktop\" header_2_font_size_tablet=\"36px\" header_2_font_size_phone=\"34px\" header_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22header_2_text_color%22%93}\" sticky_enabled=\"0\" text_orientation=\"center\"]<h2>What <span class=\"clr-txt\">Food Safety</span> Means To Us — And Why It Matters</h2>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_2,1_4\" use_custom_gutter=\"on\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"40px||||false|false\" custom_padding=\"0px||0px||true|false\" hover_enabled=\"0\" locked=\"off\" global_colors_info=\"{}\" sticky_enabled=\"0\"][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/PalmSpring2019-scaled.webp\" alt=\"PalmSpring2019\" title_text=\"PalmSpring2019\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"#612228\" box_shadow_style=\"preset5\" box_shadow_spread=\"0px\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][et_pb_column type=\"1_2\" _builder_version=\"4.27.5\" _module_preset=\"default\" hover_enabled=\"0\" global_colors_info=\"{}\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#612228\" custom_padding=\"20px|20px|20px|20px|true|true\" sticky_enabled=\"0\"][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" sticky_enabled=\"0\" text_orientation=\"center\"]Food safety is not an afterthought at Bari Produce. It’s a responsibility we take seriously at every step of the process. \nWe believe safe food protects everyone involved, from growers and packers to buyers and consumers. Strong food safety practices support confidence in the supply chain and ensure the fruit you receive meets today’s expectations for quality and care. \nOur growers and packing partners follow established food safety protocols, with regular audits and certifications to maintain compliance. These practices help protect product integrity, preserve shelf life, and reduce risk.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/PalmSpring2019-scaled.webp\" alt=\"PalmSpring2019\" title_text=\"PalmSpring2019\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"#612228\" box_shadow_style=\"preset5\" box_shadow_spread=\"0px\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section]', 'About', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-03-02 07:23:06'