h_all=\"1px\" border_color_all=\"#612228\" custom_padding=\"20px|20px|20px|20px|true|true\" sticky_enabled=\"0\"][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" header_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_text_align=\"center\" header_text_color=\"#612228\" header_font_size=\"40px\" header_2_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_2_text_color=\"gcid-heading-color\" header_2_font_size=\"40px\" header_3_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_3_text_align=\"center\" header_3_text_color=\"#612228\" header_3_font_size=\"40px\" header_4_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_4_text_align=\"center\" header_4_text_color=\"#612228\" header_4_font_size=\"40px\" header_5_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_5_text_align=\"center\" header_5_text_color=\"#612228\" header_5_font_size=\"40px\" header_6_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" header_6_text_align=\"center\" header_6_text_color=\"#612228\" header_6_font_size=\"40px\" width=\"100%\" module_alignment=\"center\" hover_enabled=\"0\" header_font_size_tablet=\"36px\" header_font_size_phone=\"34px\" header_font_size_last_edited=\"on|desktop\" header_2_font_size_tablet=\"36px\" header_2_font_size_phone=\"34px\" header_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22header_2_text_color%22%93}\" sticky_enabled=\"0\" text_orientation=\"center\"]<h2>What <span class=\"clr-txt\">Food Safety</span> Means To Us — And Why It Matters</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\" sticky_enabled=\"0\" text_orientation=\"center\"]<p>Food safety is not an afterthought at Bari Produce. It’s a responsibility we take seriously at every step of the process.<br />We believe safe food protects everyone involved, from growers and packers to buyers and consumers. Strong food safety practices support confidence in the supply chain and ensure the fruit you receive meets today’s expectations for quality and care.<br />Our growers and packing partners follow established food safety protocols, with regular audits and certifications to maintain compliance. These practices help protect product integrity, preserve shelf life, and reduce risk.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/grapes_img-scaled.webp\" alt=\"PalmSpring2019\" title_text=\"grapes_img\" _builder_version=\"4.27.5\" _module_preset=\"default\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"#612228\" box_shadow_style=\"preset5\" box_shadow_spread=\"0px\" global_colors_info=\"{}\" sticky_enabled=\"0\" custom_margin=\"||||false|false\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" background_enable_color=\"off\" filter_saturate__hover=\"0%\" filter_saturate__hover_enabled=\"on|desktop\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" next_background_color=\"#ffffff\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_color=\"#612228\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"rgba(26,26,26,0.53) 0%|rgba(26,26,26,0.47) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/02/green-grapes-scaled.webp\" parallax=\"on\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" top_divider_height=\"30px\" bottom_divider_style=\"wave\" bottom_divider_height=\"40px\" hover_enabled=\"0\" global_colors_info=\"{}\" locked=\"off\" alt=\"green-grapes\" title_text=\"green-grapes\" sticky_enabled=\"0\"][et_pb_row column_structure=\"1_3,2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"10%\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][/et_pb_column][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_horizontal_motion_enable=\"on\" scroll_horizontal_motion=\"0|50|50|100|0.5|0|-0.2\" scroll_horizontal_motion_tablet=\"0|50|50|100|0|0|0\" scroll_horizontal_motion_phone=\"0|50|50|100|0|0|0\" scroll_horizontal_motion_last_edited=\"on|tablet\" border_radii=\"on|16px|16px|16px|16px\" box_shadow_style=\"preset4\" global_colors_info=\"{}\"][et_pb_heading title=\"Why Buyers Choose Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_direction=\"top\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_heading title=\"We are smaller by design, and hands-on by choice.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_direction=\"top\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<p>We’re intentionally structured to stay involved. Orders aren’t passed along anonymously. They’re managed by people who understand fruit, timing, and what’s at stake when product hits the dock.</p>\n<p>We stay close to the field, close to our trusted growers, and accountable through every delivery. That’s how we continue to deliver fruit that is consistent in size, flavor, and appearance - even during busy seasons.</p>\n<p>Ordering is straightforward. Communication is clear. And expectations are met without needing reminders.</p>[/et_pb_text][et_pb_heading title=\"We’re big enough to deliver—and small enough to care.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_button button_text