\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"]<h2>Industry Affiliations</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"#FFFFFF\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" global_colors_info=\"{}\"]<p>Bari Produce is proud to be actively engaged in the produce industry. Our affiliations reflect our commitment to professionalism, accountability, and staying informed as the marketplace evolves.</p>\n<p>We value collaboration, shared standards, and ongoing learning because delivering consistent quality requires staying connected to the industry as a whole.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"3_5\" module_class=\"logo-column\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" title_text=\"logos-7-1\" module_class=\" image-logo\" _builder_version=\"4.27.5\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1.png\" title_text=\"logos-7-1\" module_class=\" image-logo\" _builder_version=\"4.27.5\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/logos-7-1