%22%93}\" animation_style=\"slide\" animation_intensity_slide=\"8%\" sticky_enabled=\"0\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font|500|||||||\" text_text_color=\"#612228\" text_font_size=\"20px\" hover_enabled=\"0\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" sticky_enabled=\"0\"]<p>The highest compliment is when we hear <em>“I saw your fruit in the store. It looked so good, I had to buy it!”</em></p>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font||||||||\" text_text_color=\"#1A1A1A\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\"]Our labels mean we are proud of our product. Not everything makes the cut, and that’s intentional. \nWe prioritize long-term relationships over short-term volume, and we protect the standards that buyers trust.[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/02/BariProduceGrapeBo.png\" alt=\"BariProduceGrapeBox\" title_text=\"BariProduceGrapeBox\" _builder_version=\"4.27.5\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|0|0|0\" scroll_vertical_motion_phone=\"0|50|50|100|0|0|0\" scroll_vertical_motion_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" make_equal=\"on\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"50px||||false|false\" custom_mar