(399, 2, '2026-03-03 06:28:52', '2026-03-03 06:28:52', '[et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" use_background_color_gradient=\"on\" background_color_gradient_direction=\"90deg\" background_color_gradient_stops=\"#612228 0%|rgba(112,34,42,0.5) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/02/Flavorosa-Plum_B-1-scaled.webp\" background_position=\"center_right\" background_horizontal_offset=\"0%\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{}\"][et_pb_column type=\"4_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Bari Produce Delivers Fruit Customers Come Back For, Week After Week\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_font_size=\"56px\" width=\"75%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"42px\" title_font_size_phone=\"36px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_heading title=\"Central California Grown Fruit, From A Family That’s Been Doing This For Generations\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_font_size=\"22px\" title_line_height=\"1.4em\" width=\"60%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edi