 and certifications to maintain compliance. These practices help protect product integrity, preserve shelf life, and reduce risk.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/grapes_img-scaled.webp\" alt=\"PalmSpring2019\" title_text=\"grapes_img\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" custom_margin=\"||||false|false\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|0|0|0\" scroll_vertical_motion_phone=\"0|50|50|100|0|0|0\" scroll_vertical_motion_last_edited=\"on|phone\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"#612228\" box_shadow_style=\"preset5\" box_shadow_spread=\"0px\" global_colors_info=\"{}\" filter_saturate__hover=\"0%\" filter_saturate__hover_enabled=\"on|desktop\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" prev_background_color=\"#ffffff\" next_background_color=\"#ffffff\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_color=\"#612228\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"rgba(26,26,26,0.53) 0%|rgba(26,26,26,0.47) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/03/certificate-banner-scaled.webp\" parallax=\"on\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" top_divider_style=\"wave\" top_divider_height=\"20px\" bottom_divider_style=\"wave\" bottom_divider_height=\"20px\" bottom_divider_repeat_tablet=\"\" bottom_divider_repeat_phone=\"\" bottom_divider_repeat_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][et_pb_row column_struc