ion=\"4.27.5\" _module_preset=\"default\" background_color=\"#612228\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"rgba(26,26,26,0.53) 0%|rgba(26,26,26,0.47) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/02/crazy-apes-scaled.webp\" parallax=\"on\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" top_divider_height=\"30px\" bottom_divider_style=\"wave\" bottom_divider_height=\"40px\" global_colors_info=\"{}\"][et_pb_row column_structure=\"1_3,2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"10%\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][/et_pb_column][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_color=\"#FFFFFF\" custom_padding=\"20px|20px|20px|20px|true|true\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_horizontal_motion_enable=\"on\" scroll_horizontal_motion=\"0|50|50|100|0.5|0|-0.2\" scroll_horizontal_motion_tablet=\"0|50|50|100|0|0|0\" scroll_horizontal_motion_phone=\"0|50|50|100|0|0|0\" scroll_horizontal_motion_last_edited=\"on|tablet\" border_radii=\"on|16px|16px|16px|16px\" box_shadow_style=\"preset4\" global_colors_info=\"{}\"][et_pb_heading title=\"Why Buyers Choose Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_direction=\"top\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_heading title=\"We are smaller by design, and hands-on by choice.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_direction=\"top\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<p>We’re intentionally structured to stay involved. Orders aren’t passed along anonymously. They’re managed by people who understand fruit, timing, and what’s at stake when product hits the dock.</p>\n<p>We stay close to the field, close to our trusted growers, and accountable through every delivery. That’s how we continue to deliver fruit that is consistent in size, flavor, and appearance - even during busy seasons.</p>\n<p>Ordering is straightforward. Communication is clear. And expectations are met without needing reminders.</p>[/et_pb_text][et_pb_heading title=\"We’re big enough to deliver—and small enough to care.\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_button button_text=\"Get a Custom Quote\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button