padding_phone=\"20px||40px||false|false\" border_radii=\"on|12px|12px|12px|12px\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"3_5\" _builder_version=\"4.16\" custom_padding=\"5%|5%|5%|5%\" custom_padding_tablet=\"0px|0px|0px|0px\" custom_padding_last_edited=\"off|desktop\" global_colors_info=\"{}\" padding_tablet=\"0px|0px|0px|0px\" padding_last_edited=\"off|desktop\" custom_padding__hover=\"|||\"][et_pb_heading title=\"Grown in Central California, Timed to the Season\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"#FFFFFF\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" text_font=\"||||||||\" text_line_height=\"1.8em\" header_font=\"||||||||\" background_layout=\"dark\" module_alignment=\"left\" custom_margin=\"||20px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" locked=\"off\" global_colors_info=\"{}\"]<p>Central California’s climate gives us an advantage, and we know how to use it. Long growing days, experienced growers, and deep regional knowledge allow us to time harvests carefully and deliver predictable quality.<br />From early windows like Crazy Apes™ apricots to peak-season stone fruit and grapes, our programs are built around timing, experience, and restraint.</p>[/et_pb_text][et_pb_button button_text=\"View Seasonal Availability \" button_alignment=\"left\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\"