|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"3_5,2_5\" use_custom_gutter=\"on\" gutter_width=\"1\" custom_padding_last_edited=\"on|tablet\" admin_label=\"Feature 02 Area\" module_class=\"d-flex\" _builder_version=\"4.27.5\" background_color=\"#612228\" width=\"90%\" overflow-x=\"visible\" overflow-y=\"visible\" custom_margin=\"0px||0px||false|false\" custom_padding=\"0px|0px|0px|0px\" custom_padding_tablet=\"20px|0px|40px|0px|false|false\" custom_padding_phone=\"20px||40px||false|false\" border_radii=\"on|12px|12px|12px|12px\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"3_5\" _builder_version=\"4.16\" custom_padding=\"5%|5%|5%|5%\" custom_padding_tablet=\"0px|0px|0px|0px\" custom_padding_last_edited=\"off|desktop\" global_colors_info=\"{}\" padding_tablet=\"0px|0px|0px|0px\" padding_last_edited=\"off|desktop\" custom_padding__hover=\"|||\"][et_pb_heading title=\"Grown in Central California, Timed to the Season\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"#FFFFFF\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" text_font=\"||||||||\" text_font_size=\"18px\" header_font=\"||||||||\" background_layout=\"dark\" module_alignment=\"left\" custom_margin=\"||20px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" hover_enabled=\"0\" locked=\"off\" global_colors_info=\"{}\" text_line_height=\"1.7em\" sticky_enabled=\"0\"]<p>Central California’s climate gives us an advantage, and we know how to use it. Long growing days, experienced growers, and deep regional knowledge allow us to time harvests carefully and deliver predictable quality.<br />From early windows like Crazy Apes™ apricots to peak-season stone fruit and grapes, our programs are built around timing, experience, and restraint.</p>[/et_pb_text][et_pb_button button_text=\"View Seasonal Availability \" button_alignment=\"left\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#9B693F\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" locked=\"off\" global_colors_info=\"{}\" button_text_color__hover_enabled=\"on|hover\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column type=\"2_5\" _builder_version=\"4.16\" custom_padding=\"|||\" global_colors_info=\"{}\" custom_padding__hover=\"|||\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/nature2-scaled.webp\" alt=\"nature2\" title_text=\"nature2\" force_fullwidth=\"on\" align_tablet=\"center\" align_phone=\"\" align_last_edited=\"on|phone\" _builder_version=\"4.27.6\" transform_scale_tablet=\"\" transform_scal