(717, 1, '2026-04-01 00:20:47', '2026-04-01 00:20:47', '[et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" use_background_color_gradient=\"on\" background_color_gradient_direction=\"90deg\" background_color_gradient_stops=\"#612228 0%|rgba(112,34,42,0.5) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/03/bari-banner-scaled.webp\" background_position=\"center_right\" background_horizontal_offset=\"0%\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{}\"][et_pb_column type=\"4_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Bari Produce Delivers Fruit Customers Come Back For, Week After Week\" _builder_version=\"4.27.6\" _module_preset=\"default\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_font_size=\"56px\" title_line_height=\"1.1em\" width=\"75%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"42px\" title_font_size_phone=\"36px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_heading title=\"Central California Grown Fruit, From A Family That’s Been Doing This For Generations\" _builder_version=\"4.27.6\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#FFFFFF\" title_font_size=\"22px\" title_line_height=\"1.4em\" width=\"60%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_text_color=\"#FFFFFF\" width=\"70%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||30px||false|false\" global_colors_info=\"{}\"]<p>We believe great fruit starts with care, experience, and accountability. That’s how we’ve done it for generations—and how we continue to serve today’s marketplace.</p>[/et_pb_text][et_pb_button button_text=\"Contact Us for More Information\" button_alignment=\"left\" _builder_version=\"4.27.6\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#9B693F\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" hover_enabled=\"0\" global_colors_info=\"{}\" button_text_color__hover_enabled=\"on|hover\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\" button_url=\"@ET-DC@eyJkeW5hbWljIjp0cnVlLCJjb250ZW50IjoicG9zdF9saW5rX3VybF9wYWdlIiwic2V0dGluZ3MiOnsicG9zdF9pZCI6IjIxIn19@\" _dynamic_attributes=\"button_url\" sticky_enabled=\"0\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_image=\"off\" background_size=\"custom\" background_image_width=\"13%\" background_position=\"top_left\" background_horizontal_offset=\"-7%\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"3_5,2_5\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"3_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Our Family Approach To Consistent Quality and Reliable Service\" _builder_version=\"4.27.6\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" title_line_height=\"1.2em\" width=\"80%\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" global_colors_info=\"{%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<p>Our roots trace back to family farming and the open markets of Bari, Italy, where freshness, care, and pride shaped how produce was grown, sold, and valued. Those values carried our family to Central California and continue today through how we manage sales, standards, and stewardship.<br />The standards that mattered to our patriarch in Italy still guide us today. They show up in how we select fruit, how we work with growers, and how we serve our customers.</p>[/et_pb_text][et_pb_button button_text=\"The Story Behind Bari Produce\" _builder_version=\"4.27.5\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#612228\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_style=\"slide\" animation_direction=\"top\" animation_intensity_slide=\"10%\" global_colors_info=\"{}\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color__hover_enabled=\"on|hover\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate__hover=\"8px|0px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column type=\"2_5\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/04/IMG_1729.JPG-e1775002823206.jpeg\" alt=\"about family\" title_text=\"IMG_1729.JPG\" _builder_version=\"4.27.6\" _module_preset=\"default\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"10%\" hover_enabled=\"0\" border_radii=\"on|16px|16px|16px|16px\" border_width_bottom=\"6px\" border_color_bottom=\"#906469\" global_colors_info=\"{}\" border_width_bottom__hover_enabled=\"on|hover\" filter_contrast__hover_enabled=\"on|desktop\" filter_saturate__hover_enabled=