|false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Bari Fruit Makes Your Shelves Look Good\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22title_text_color%22%93}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font|500|||||||\" text_text_color=\"#612228\" text_font_size=\"20px\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"]<p>The highest compliment is when we hear <em>“I saw your fruit in the store. It looked so good, I had to buy it!”</em></p>[/et_pb_text][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_font=\"--et_global_body_font||||||||\" text_text_color=\"#1A1A1A\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"]<p>Our labels mean we are proud of our product. Not everything makes the cut, and that’s intentional.<br />We prioritize long-term relationships over short-term volume, and we protect the standards that buyers trust.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5