dy-color%22:%91%22text_text_color%22%93}\"]<p>Bari Produce is proud to be actively engaged in the produce industry. Our affiliations reflect our commitment to professionalism, accountability, and staying informed as the marketplace evolves.</p>\n<p>We value collaboration, shared standards, and ongoing learning because delivering consistent quality requires staying connected to the industry as a whole.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"3_5\" module_class=\"logo-column\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/BB_Trading_Member.svg\" alt=\"cffa\" title_text=\"BB_Trading_Member\" module_class=\" image-logo\" _builder_version=\"4.27.6\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/pomegrante-council.svg\" title_text=\"pomegrante-council\" module_class=\" image-logo\" _builder_version=\"4.27.6\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/cffa.svg\" title_text=\"cffa\" module_class=\" image-logo\" _builder_version=\"4.27.6\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/wga_logo.svg\" title_text=\"wga_logo\" module_class=\" image-logo\" _builder_version=\"4.27.6\" _module_preset=\"default\" border_radii=\"on|4px|4px|4px|4px\" border_width_all=\"1px\" border_color_all=\"#FFFFFF\" global_colors_info=\"{}\"][/et_pb_image][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/ctgc.svg\" title_text=