ader_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22header_2_text_color%22,%22header_2_text_color%22%93,%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<h2>What <span class=\"clr-txt\">Food Safety</span> Means To Us — And Why It Matters</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" text_orientation=\"center\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22header_2_text_color%22%93,%22gcid-body-color%22:%91%22text_text_color%22,%22text_text_color%22%93}\"]<p>Food safety is not an afterthought at Bari Produce. It’s a responsibility we take seriously at every step of the process.<br />We believe safe food protects everyone involved, from growers and packers to buyers and consumers. Strong food safety practices support confidence in the supply chain and ensure the fruit you receive meets today’s expectations for quality and care.<br />Our growers and packing partners follow established food safety protocols, with regular audits and certifications to maintain compliance. These practices help protect product integrity, preserve shelf life, and reduce risk.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/grapes_img-scaled.webp\" alt=\"PalmSpring2019\" title_text=\"grapes_img\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_enable_color=\"off\" custom_margin=\"||||false|false\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|0|0|0\" scroll_vertical_motion_phone=\"0|50|50|100|0|0|0\" scroll_vertical_motion_last_edited=\"on|phone\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"#612228\" box_shadow_style=\"preset5\" box_shadow_spread=\"0px\" global_colors_info=\"{}\" filter_saturate__hover=\"0%\" filter_saturate__hover_enabled=\"on|desktop\"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" prev_background_color=\"#ffffff\" next_background_color=\"#ffffff\" _builder_version=\"4.27.5\" _module_preset=\"default\" background_color=\"#612228\" use_background_color_gradient=\"on\" background_color_gradient_stops=\"rgba(26,26,26,0.53) 0%|rgba(26,26,26,0.47) 100%\" background_color_gradient_overlays_image=\"on\" background_image=\"https://bariproduce.com/wp-content/uploads/2026/03/certificate-banner-scaled.webp\" parallax=\"on\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" top_divider_style=\"wave\" top_divider_height=\"20px\" bottom_divider_style=\"wave\" bottom_divider_height=\"20px\" bottom_divider_repeat_tablet=\"\" bottom_divider_repeat_phone=\"\" bottom_divider_repeat_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][et_pb_row column_structure=\"1_3,2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_padding=\"0px||0px||true|false\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"10%\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\