"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||10px||false|false\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_text_color=\"#FFFFFF\" width=\"70%\" width_tablet=\"100%\" width_phone=\"100%\" width_last_edited=\"on|tablet\" custom_margin=\"||30px||false|false\" global_colors_info=\"{}\"]<p>We believe great fruit starts with care, experience, and accountability. That’s how we’ve done it for generations—and how we continue to serve today’s marketplace.</p>[/et_pb_text][et_pb_button button_url=\"@ET-DC@eyJkeW5hbWljIjp0cnVlLCJjb250ZW50IjoicG9zdF9saW5rX3VybF9wYWdlIiwic2V0dGluZ3MiOnsicG9zdF9pZCI6IjIxIn19@\" button_text=\"Contact Us for More Information\" button_alignment=\"left\" _builder_version=\"4.27.6\" _dynamic_attributes=\"button_url\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#9B693F\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" global_colors_info=\"{}\" button_text_color__hover_enabled=\"on|hover\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" transform_skew__hover_enabled=\"on|desktop\" transform_origin__hover_enabled=\"on|desktop\" transform_translate__hover=\"0px|-7px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_pad