%\" module_alignment=\"left\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"8%\" header_font_size_tablet=\"36px\" header_font_size_phone=\"34px\" header_font_size_last_edited=\"on|desktop\" header_2_font_size_tablet=\"36px\" header_2_font_size_phone=\"34px\" header_2_font_size_last_edited=\"on|desktop\" header_3_font_size_tablet=\"36px\" header_3_font_size_phone=\"34px\" header_3_font_size_last_edited=\"on|desktop\" header_4_font_size_tablet=\"36px\" header_4_font_size_phone=\"34px\" header_4_font_size_last_edited=\"on|desktop\" header_5_font_size_tablet=\"36px\" header_5_font_size_phone=\"34px\" header_5_font_size_last_edited=\"on|desktop\" header_6_font_size_tablet=\"36px\" header_6_font_size_phone=\"34px\" header_6_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22header_2_text_color%22%93,%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<h2>Our Growers Are <span class=\"clr-txt\">Third-Generation Farming Families</span>, Working Together</h2>[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22header_2_text_color%22%93,%22gcid-body-color%22:%91%22text_text_color%22,%22text_text_color%22%93}\"]We partner with growers who share our values and our commitment to quality. Many are third-generation farming families with deep roots in Central California agriculture. These are relationships built over time, grounded in trust, and strengthened by shared standards.[/et_pb_text][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22heade