tom_padding=\"0px||0px||true|false\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Our Bari Fruit\" _builder_version=\"4.27.6\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" title_line_height=\"1.4em\" custom_margin=\"||0px||false|false\" custom_padding=\"||0px||false|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_heading title=\"We offer tried-and-true favorites as well as new varieties. Our lineup includes:\" _builder_version=\"4.27.6\" _module_preset=\"default\" title_level=\"h5\" title_font=\"Inter|600|||||||\" title_text_align=\"left\" title_text_color=\"#612228\" title_font_size=\"22px\" title_line_height=\"1.4em\" custom_margin=\"||0px||false|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" title_font_size_tablet=\"22px\" title_font_size_phone=\"20px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_text_color=\"gcid-body-color\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93,%22gcid-body-color%22:%91%22text_text_color%22%93}\"]<p><strong>Table Grapes</strong> under the BARI® and LOGOLUSO® labels and standards<br /><strong>Stone Fruit</strong> such as peaches, nectarines, plums, pluots, and cherries.<br /><strong>Specialty &amp; Seasonal Varieties</strong> like our popular Crazy Apes™ extra large apricots and fall fruits (Pomegranates and Persimmons) that are all hand-picked and fresh-packed.</p>[/et_pb_text][et_pb_button button_url=\"@ET-DC@eyJkeW5hbWljIjp0cnVlLCJjb250ZW50IjoicG9zdF9saW5rX3VybF9wYWdlIiwic2V0dGluZ3MiOnsicG9zdF9pZCI6IjQwNyJ9fQ==@\" button_text=\"View All Our Products\" _builder_version=\"4.27.6\" _dynamic_attributes=\"button_url\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#612228\" button_border_width=\"2px\" button_border_color=\"#612228\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" locked=\"off\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" button_bg_color__hover=\"#2C470E\" button_bg_color__hover_enabled=\"on|hover\" button_text_color__hover_enabled=\"on|hover\" button_border_color__hover=\"#2C470E\" button_border_color__hover_enabled=\"on|hover\" button_bg_enable_color__hover=\"on\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|hover\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|hover\" transform_skew__hover_enabled=\"on|hover\" transform_origin__hover_enabled=\"on|hover\" transform_translate__hover=\"8px|0px\" button_text_color__hover=\"#FFFFFF\"][/et_pb_button][/et_pb_column][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_gallery gallery_ids=\"531,534,489,375\" show_title_and_caption=\"off\" show_pagination=\"off\" zoom_icon_color=\"#FFFFFF\" hover_overlay_color=\"rgba(113,56,62,0.74)\" hover_icon=\"&#x2d;||divi||400\" module_class=\"products-gallery \" _builder_version=\"4.27.6\" _module_preset=\"default\" custom_margin=\"||0px||false|false\" custom_padding=\"||||false|false\" border_radii_image=\"on|12px|12px|12px|12px\" global_colors_info=\"{}\" background__hover_enabled=\"on|desktop\"][/et_pb_gallery][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" overflow-x=\"visible\" overflow-y=\"visible\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"3_5,2_5\" use_custom_gutter=\"on\" gutter_width=\"1\" custom_padding_last_edited=\"on|tablet\" admin_label=\"Feature 02 Area\" module_class=\"d-flex\" _builder_version=\"4.27.5\" background_color=\"#612228\" width=\"90%\" overflow-x=\"visible\" overflow-y=\"visible\" custom_margin=\"0px||0px||false|false\" custom_padding=\"0px|0px|0px|0px\" custom_padding_tablet=\"20px|0px|40px|0px|false|false\" custom_padding_phone=\"20px||40px||false|false\" border_radii=\"on|12px|12px|12px|12px\" locked=\"off\" global_colors_info=\"{}\"][et_pb_column type=\"3_5\" _builder_version=\"4.16\" custom_padding=\"5%|5%|5%|5%\" custom_padding_tablet=\"0px|0px|0px|0px\" custom_padding_last_edited=\"off|desktop\" global_colors_info=\"{}\" padding_tablet=\"0px|0px|0px|0px\" padding_last_edited=\"off|desktop\" custom_padding__hover=\"|||\"][et_pb_heading title=\"Grown in Central California, Timed to the Season\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"#FFFFFF\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.6\" text_font=\"||||||||\" header_font=\"||||||||\" background_layout=\"dark\" module_alignment=\"left\" custom_margin=\"||20px||false|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" locked=\"off\" global_colors_info=\"{}\"]<p>Central California’s climate gives us an advantage, and we know how to use it. Long growing days, experienced growers, and deep regional knowledge allow us to time harvests carefully and deliver predictable quality.<br />From early windows like Crazy Apes™ apricots to peak-season stone fruit and grapes, our programs are built around timing, experience, and restraint.</p>[/et_pb_text][et_pb_button button_url=\"@ET-DC@eyJkeW5hbWljIjp0cnVlLCJjb250ZW50IjoicG9zdF9saW5rX3VybF9wYWdlIiwic2V0dGluZ3MiOnsicG9zdF9pZCI6IjIxIn19@\" button_text=\"Contact Us for More Information\" button_alignment=\"left\" _builder_version=\"4.27.6\" _dynamic_attributes=\"button_url\" _module_preset=\"default\" custom_button=\"on\" button_text_size=\"16px\" button_text_color=\"#FFFFFF\" button_bg_color=\"#9B693F\" button_border_width=\"2px\" button_border_color=\"#9B693F\" button_border_radius=\"16px\" button_on_hover=\"off\" transform_translate_linked__hover=\"off\" custom_padding=\"10px|40px|10px|20px|true|false\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" animation_starting_opacity=\"100%\" locked=\"off\" global_colors_info=\"{}\" button_text_color__hover_enabled=\"on|hover\" button_bg_color__hover_enabled=\"on|hover\" button_bg_color__hover=\"#2C470E\" button_bg_enable_color__hover=\"on\" button_border_color__hover_enabled=\"on|desktop\" button_border_color__hover=\"#2C470E\" transform_styles__hover_enabled=\"on|hover\" transform_scale__hover_enabled=\"on|desktop\" transform_translate__hover_enabled=\"on|hover\" transform_rotate__hover_enabled=\"on|desktop\" tran