le_preset=\"default\" background_color=\"#ebe1d9\" background_enable_pattern_style=\"on\" background_pattern_color=\"rgba(255,255,255,0.17)\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" top_divider_style=\"wave\" top_divider_height=\"20px\" global_colors_info=\"{}\"][et_pb_row column_structure=\"2_3,1_3\" use_custom_gutter=\"on\" make_equal=\"on\" module_class=\"d-flex\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"||||false|false\" custom_margin_tablet=\"50px||||false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"2_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_heading title=\"Bari Fruit Makes Your Shelves Look Good\" _builder_version=\"4.27.5\" _module_preset=\"default\" title_level=\"h2\" title_font=\"--et_global_heading_font|--et_global_heading_font_weight|||||||\" title_text_color=\"gcid-heading-color\" title_font_size=\"40px\" custom_margin=\"||10px||false|false\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" title_font_size_tablet=\"36px\" title_font_size_phone=\"34px\" title_font_size_last_edited=\"on|desktop\" locked=\"off\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22,%22title_text_color%22%93}\"][/et_pb_heading][et_pb_text _builder_version=\"4.27.5\" _module_preset=\"default\" text_font=\"--et_global_body_font|500|||||||\" text_text_color=\"#612228\" text_font_size=\"20px\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"]<p>The highest compliment is when we hear <em>“I saw your fruit in the store. It looked so good, I had to buy it!”</em></p>[/et_pb_text][et_pb_text _builder_version=\"4.27.6\" _module_preset=\"default\" text_font=\"--et_global_body_font||||||||\" text_text_color=\"#1A1A1A\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\"]<p>Our labels mean we are proud of our product. Not everything makes the cut, and that’s intentional.<br />We prioritize long-term relationships over short-term volume, and we protect the standards that buyers trust.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_3\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_image src=\"https://bariproduce.com/wp-content/uploads/2026/03/Candy-Snaps-Transparent-scaled.png\" alt=\"grapes-bari\" title_text=\"Candy Snaps Transparent\" _builder_version=\"4.27.6\" _module_preset=\"default\" scroll_vertical_motion_enable=\"on\" scroll_vertical_motion=\"0|50|50|100|-0.5|0|0.5\" scroll_vertical_motion_tablet=\"0|50|50|100|0|0|0\" scroll_vertical_motion_phone=\"0|50|50|100|0|0|0\" scroll_vertical_motion_last_edited=\"on|desktop\" global_colors_info=\"{}\"][/et_pb_image][/et_pb_column][/et_pb_row][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" make_equal=\"on\" _builder_version=\"4.27.5\" _module_preset=\"default\" width=\"90%\" custom_margin=\"50px||||false|false\" custom_margin_tablet=\"50px||||false|false\" custom_margin_phone=\"0px||||false|false\" custom_margin_last_edited=\"on|phone\" custom_padding=\"0px||0px||true|false\" global_colors_info=\"{}\"][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"01\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"left\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover_enabled=\"on|hover\" header_text_color__hover=\"#FFFFFF\"]<p>Stronger displays that hold their shape.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"02\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Fewer calls about condition or hold.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"03\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Better sell-through and cleaner rotation.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"04\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Less mental load managing one more variable.</p>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" overflow-x=\"visible\" overflow-y=\"visible\" custom_padding=\"80px||80px||true|false\" custom_padding_tablet=\"70px||70px||true|false\" custom_padding_phone=\"60px||60px||true|false\" global_colors_info=