0|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"bottom\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Better sell-through and cleaner rotation.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.27.5\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"04\" module_class=\"blurb-stroke\" _builder_version=\"4.27.5\" _module_preset=\"default\" header_level=\"h2\" header_font=\"Inter|700|||||||\" header_text_align=\"left\" header_text_color=\"#612228\" header_font_size=\"80px\" body_font=\"Inter||||||||\" body_text_color=\"#FFFFFF\" background_color=\"#612228\" height=\"100%\" custom_padding=\"20px|20px|20px|20px|true|true\" animation_style=\"slide\" animation_direction=\"right\" animation_intensity_slide=\"8%\" custom_css_free_form=\"selector h2{||  padding-bottom: 20px;||}\" header_text_shadow_style=\"preset5\" border_radii=\"on|12px|12px|12px|12px\" border_color_all=\"RGBA(255,255,255,0)\" global_colors_info=\"{%22gcid-heading-color%22:%91%22title_text_color%22%93}\" header_text_color__hover=\"#FFFFFF\" header_text_color__hover_enabled=\"on|hover\"]<p>Less mental load managing one more variable.</p>[/et_pb_blurb][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" custom_padding_last_edited=\"on|phone\" _builder_version=\"4.27.5\" _module_preset=\"default\" overflow-x=\"visible\" overflow-y=\"visible\" custom_padding=\"80px||8